import { describe, it, expect, beforeAll } from "vitest";
import { readFileSync, existsSync } from "node:fs";

/* The service worker is generated by `offlinePlugin` in vite.config.js and
 * only exists after a build, so this suite runs against `dist/sw.js`.
 *
 * Testing it matters more than most things here: a service worker is the one
 * piece of the app that can serve *stale* code to a returning user, and its
 * mistakes are invisible until someone is offline on a train. The registration
 * itself needs a real browser; what is checked here is the policy, which is
 * the part that was written by hand.
 */

const SW = "dist/sw.js";
const built = existsSync(SW);
const describeIfBuilt = built ? describe : describe.skip;

describeIfBuilt("generated service worker", () => {
  let scope, source;

  /** A minimal ServiceWorkerGlobalScope, enough to run the worker's handlers. */
  function makeScope() {
    const stores = new Map();
    const handlers = {};
    const cacheApi = {
      _stores: stores,
      open: async (name) => {
        if (!stores.has(name)) stores.set(name, new Map());
        const store = stores.get(name);
        return {
          addAll: async (urls) => urls.forEach((u) => store.set(u, { url: u, ok: true })),
          put: async (req, res) => store.set(req.url || req, res),
          keys: async () => [...store.keys()],
        };
      },
      keys: async () => [...stores.keys()],
      delete: async (name) => stores.delete(name),
      match: async (req) => {
        const key = req?.url || req;
        for (const store of stores.values()) if (store.has(key)) return store.get(key);
        return undefined;
      },
    };
    return {
      handlers,
      caches: cacheApi,
      location: { origin: "https://example.test" },
      addEventListener: (type, fn) => { handlers[type] = fn; },
      skipWaiting: () => {},
      clients: { claim: () => {} },
    };
  }

  /* The worker is compiled with `fetch` bound once, so the network stub has to
   * be swapped through an indirection rather than reassigned afterwards. */
  let network = () => Promise.reject(new Error("offline"));

  /** Run one fetch handler and return what it chose to respond with, if anything. */
  async function runFetch(scopeObj, request, networkResult) {
    network = networkResult;
    let responded;
    scopeObj.handlers.fetch({ request, respondWith: (p) => { responded = p; } });
    return responded === undefined ? undefined : await responded;
  }

  beforeAll(async () => {
    source = readFileSync(SW, "utf8");
    scope = makeScope();
    const run = new Function("self", "caches", "URL", "fetch", source);
    run(scope, scope.caches, URL, (...args) => network(...args));

    // Install, so the precache is populated for the tests below.
    let installed;
    scope.handlers.install({ waitUntil: (p) => { installed = p; } });
    await installed;
  });

  it("precaches the whole built app, not just the code", () => {
    const list = JSON.parse(source.match(/const PRECACHE = (\[[\s\S]*?\]);/)[1]);
    expect(list).toContain("/");
    expect(list).toContain("/index.html");
    expect(list.some((f) => f.endsWith(".js"))).toBe(true);
    expect(list.some((f) => f.endsWith(".css"))).toBe(true);
    /* The word images are what the picture-choice exercise draws; without
     * them the exercise is blank offline while everything else works. */
    expect(list.some((f) => f.startsWith("/img/"))).toBe(true);
    expect(list).toContain("/manifest.webmanifest");
  });

  it("names the cache from a hash of the file list, so a new build evicts the old", () => {
    const name = source.match(/const CACHE = "(.*?)"/)[1];
    expect(name).toMatch(/^vd-[0-9a-f]{12}$/);
  });

  it("serves a precached asset without touching the network", async () => {
    const list = JSON.parse(source.match(/const PRECACHE = (\[[\s\S]*?\]);/)[1]);
    const asset = list.find((f) => f.endsWith(".js"));
    const res = await runFetch(scope, {
      method: "GET", mode: "no-cors",
      url: `https://example.test${asset}`,
      /* `caches.match` in the real API normalises to the URL; the stub keys on
       * whatever `url` says, so the request carries the path it was cached
       * under. */
      toString: () => asset,
    }, () => Promise.reject(new Error("network should not have been used")));
    expect(res).toBeDefined();
  });

  it("falls back to the cached shell when a navigation cannot reach the network", async () => {
    /* The offline case that matters: opening the app on a train. */
    const res = await runFetch(scope, {
      method: "GET", mode: "navigate",
      url: "https://example.test/",
    }, () => Promise.reject(new Error("offline")));
    expect(res.url).toBe("/index.html");
  });

  it("prefers the network for navigations when there is one", async () => {
    // Otherwise a deploy would never be picked up.
    const fresh = { url: "from-network", ok: true };
    const res = await runFetch(scope, {
      method: "GET", mode: "navigate",
      url: "https://example.test/",
    }, () => Promise.resolve(fresh));
    expect(res).toBe(fresh);
  });

  it("never caches the API", async () => {
    /* Lookup and fact-check are honestly unavailable offline. A stale cached
     * gloss is worse than the failure message the app already shows. */
    const res = await runFetch(scope, {
      method: "GET", mode: "cors",
      url: "https://example.test/api/gloss",
    }, () => Promise.reject(new Error("offline")));
    expect(res).toBeUndefined();
  });

  it("leaves other origins alone", async () => {
    const res = await runFetch(scope, {
      method: "GET", mode: "cors",
      url: "https://fonts.googleapis.test/css",
    }, () => Promise.reject(new Error("offline")));
    expect(res).toBeUndefined();
  });

  it("does not intercept writes", async () => {
    const res = await runFetch(scope, {
      method: "POST", mode: "cors",
      url: "https://example.test/api/verify",
    }, () => Promise.reject(new Error("offline")));
    expect(res).toBeUndefined();
  });
});
